    var slider=document.getElementById('heroSlider'),slides=slider?Array.prototype.slice.call(slider.querySelectorAll('.slide')):[],dotsBox=document.getElementById('sliderDots'),current=0,timer;
    function showSlide(index){if(!slides.length)return;current=(index+slides.length)%slides.length;slides.forEach(function(slide,i){slide.classList.toggle('active',i===current);slide.setAttribute('aria-hidden',i===current?'false':'true')});if(dotsBox)Array.prototype.forEach.call(dotsBox.children,function(dot,i){dot.classList.toggle('active',i===current);dot.setAttribute('aria-selected',i===current?'true':'false')})}
    if(slides.length>1&&dotsBox){slides.forEach(function(_,i){var dot=document.createElement('button');dot.type='button';dot.setAttribute('role','tab');dot.setAttribute('aria-label','Show slide '+(i+1));dot.addEventListener('click',function(){showSlide(i);restart()});dotsBox.appendChild(dot)});document.getElementById('prevSlide').addEventListener('click',function(){showSlide(current-1);restart()});document.getElementById('nextSlide').addEventListener('click',function(){showSlide(current+1);restart()});function restart(){clearInterval(timer);timer=setInterval(function(){showSlide(current+1)},6000)}showSlide(0);restart()}
    var testimonialCarousel=document.getElementById('testimonialCarousel');
    if(testimonialCarousel){var testimonialSlides=Array.prototype.slice.call(testimonialCarousel.querySelectorAll('.testimonial-slide')),testimonialDots=testimonialCarousel.querySelector('[data-testimonial-dots]'),testimonialIndex=0,testimonialTimer;function showTestimonial(index){if(!testimonialSlides.length)return;testimonialIndex=(index+testimonialSlides.length)%testimonialSlides.length;testimonialSlides.forEach(function(slide,i){slide.classList.toggle('active',i===testimonialIndex);slide.setAttribute('aria-hidden',i===testimonialIndex?'false':'true')});if(testimonialDots)Array.prototype.forEach.call(testimonialDots.children,function(dot,i){dot.classList.toggle('active',i===testimonialIndex);dot.setAttribute('aria-selected',i===testimonialIndex?'true':'false')})}function restartTestimonials(){clearInterval(testimonialTimer);if(testimonialSlides.length>1&&!window.matchMedia('(prefers-reduced-motion: reduce)').matches)testimonialTimer=setInterval(function(){showTestimonial(testimonialIndex+1)},6500)}if(testimonialSlides.length>1&&testimonialDots){testimonialSlides.forEach(function(_,i){var dot=document.createElement('button');dot.type='button';dot.setAttribute('role','tab');dot.setAttribute('aria-label','Show testimonial '+(i+1));dot.addEventListener('click',function(){showTestimonial(i);restartTestimonials()});testimonialDots.appendChild(dot)});testimonialCarousel.querySelector('[data-testimonial-prev]').addEventListener('click',function(){showTestimonial(testimonialIndex-1);restartTestimonials()});testimonialCarousel.querySelector('[data-testimonial-next]').addEventListener('click',function(){showTestimonial(testimonialIndex+1);restartTestimonials()});testimonialCarousel.addEventListener('mouseenter',function(){clearInterval(testimonialTimer)});testimonialCarousel.addEventListener('mouseleave',restartTestimonials);testimonialCarousel.addEventListener('focusin',function(){clearInterval(testimonialTimer)});testimonialCarousel.addEventListener('focusout',restartTestimonials)}showTestimonial(0);restartTestimonials()}
    var tabs=Array.prototype.slice.call(document.querySelectorAll('.tab-btn'));tabs.forEach(function(tab){tab.addEventListener('click',function(){var target=tab.dataset.panel;tabs.forEach(function(item){var active=item===tab;item.classList.toggle('active',active);item.setAttribute('aria-selected',active?'true':'false');item.tabIndex=active?0:-1});document.querySelectorAll('.tab-panel').forEach(function(panel){var active=panel.id===target;panel.classList.toggle('active',active);panel.hidden=!active})});tab.addEventListener('keydown',function(event){if(event.key==='ArrowRight'||event.key==='ArrowLeft'){event.preventDefault();var index=tabs.indexOf(tab)+(event.key==='ArrowRight'?1:-1);tabs[(index+tabs.length)%tabs.length].focus();tabs[(index+tabs.length)%tabs.length].click()}})});
    var toggle=document.getElementById('billToggle'),switcher=document.getElementById('billSwitch');function billing(mode){var yearly=mode==='yearly';if(toggle)toggle.classList.toggle('annual',yearly);if(switcher)switcher.setAttribute('aria-checked',yearly?'true':'false');document.querySelectorAll('.bill-toggle .opt').forEach(function(option){option.classList.toggle('active',option.dataset.bill===mode)});document.querySelectorAll('.p-price').forEach(function(price){price.textContent=price.dataset[mode]||price.dataset.monthly});document.querySelectorAll('.p-per').forEach(function(period){period.textContent=period.dataset[mode]||period.dataset.monthly});document.querySelectorAll('.plan-choose').forEach(function(link){link.href=link.dataset[mode+'Url']||link.dataset.monthlyUrl})}if(switcher){switcher.addEventListener('click',function(){billing(switcher.getAttribute('aria-checked')==='true'?'monthly':'yearly')});document.querySelectorAll('.bill-toggle .opt').forEach(function(option){option.addEventListener('click',function(){billing(option.dataset.bill)})})}
    document.querySelectorAll('.faq-q').forEach(function(button){button.addEventListener('click',function(){var item=button.closest('.faq-item'),answer=item.querySelector('.faq-a'),open=item.classList.contains('open');document.querySelectorAll('.faq-item.open').forEach(function(other){other.classList.remove('open');other.querySelector('.faq-q').setAttribute('aria-expanded','false');other.querySelector('.faq-a').style.maxHeight=null});if(!open){item.classList.add('open');button.setAttribute('aria-expanded','true');answer.style.maxHeight=answer.scrollHeight+'px'}})});
    var backTop=document.getElementById('backTop');window.addEventListener('scroll',function(){if(backTop)backTop.classList.toggle('show',window.scrollY>450)});if(backTop)backTop.addEventListener('click',function(){window.scrollTo({top:0,behavior:'smooth'})});
    var reveal=document.querySelectorAll('[data-reveal]');if('IntersectionObserver'in window){var observer=new IntersectionObserver(function(entries){entries.forEach(function(entry){if(entry.isIntersecting){entry.target.classList.add('revealed');observer.unobserve(entry.target)}})},{threshold:.08});reveal.forEach(function(el){observer.observe(el)})}else reveal.forEach(function(el){el.classList.add('revealed')});
})();
